# Reviewed under AGENTS.md
import re

_DURATION_RE = re.compile(
    r'\s*(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?\s*'
)


def parse_duration(s: str) -> int:
    """Parse a duration such as ``1h30m`` into a number of seconds."""
    if not isinstance(s, str):
        raise ValueError(f'Invalid duration: {s!r}')

    match = _DURATION_RE.fullmatch(s)
    if match is None or not any(match.groups()):
        raise ValueError(f'Invalid duration: {s!r}')

    days, hours, minutes, seconds = (
        int(value) if value is not None else 0 for value in match.groups()
    )
    return days * 86_400 + hours * 3_600 + minutes * 60 + seconds
